// runOnceForAllItems — explode each idea into 1 row per (réseau, format)
const resp = $input.first().json;
let text = '';
if (resp.candidates?.[0]?.content?.parts) text = resp.candidates[0].content.parts.map(p=>p.text||'').join('');
else if (typeof resp === 'string') text = resp;
else if (resp.content?.parts) text = resp.content.parts.map(p=>p.text||'').join('');
else text = JSON.stringify(resp);

function extractJson(t) {
  let c = (t||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/i,'').trim();
  try { return JSON.parse(c); } catch(e) {}
  const m = c.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch(e) {} }
  return null;
}

const data = extractJson(text) || { ideas: [] };
const out = [];
for (const idea of (data.ideas || [])) {
  const decls = Array.isArray(idea.declinaisons) && idea.declinaisons.length ? idea.declinaisons : [{ reseau: 'linkedin', format_post: 'post' }];
  for (const d of decls) {
    out.push({ json: {
      Titre: (idea.titre || 'Sans titre').substring(0,120),
      Thematique: idea.thematique || 'Autre',
      Pilier: idea.pilier || 'Autre',
      Format_Post: d.format_post || 'post',
      Reseau: d.reseau || 'linkedin',
      Brief: idea.brief || '',
      Mots_Cles: idea.mots_cles || '',
      Status: 'idée'
    }});
  }
}
return out.length ? out : [{ json: { _empty: true }}];
